function typewriterWrap(str, x, y, maxW, size, lineH, color, weight, chars, family='cjk') {
  setFont(size, weight, family, -.3);
  const arr=Array.from(str); const lines=[]; let cur='';
  for(const ch of arr){
    if(ch==='\n'){ lines.push(cur); cur=''; continue; }
    if(g.measureText(cur+ch).width>maxW && cur.length){ lines.push(cur); cur=ch; }
    else cur+=ch;
  }
  if(cur) lines.push(cur);
  let left=chars;
  let lastLine='', lastWidth=0;
  for(let i=0;i<lines.length;i++){
    if(left<=0) break;
    const part=lines[i].slice(0,left);
    g.fillStyle=color; g.textAlign='left'; g.textBaseline='alphabetic';
    g.fillText(part,x,y+i*lineH);
    lastLine=part; lastWidth=g.measureText(part).width;
    left-=lines[i].length;
    if(left<=0 && part.length<lines[i].length){ lastWidth=g.measureText(part).width; break; }
  }
  return {lines:lines.length,lastWidth,lineIndex:Math.max(0,lines.length-Math.ceil(left/100)-1)};
}
